import json,struct,sys,os
from pathlib import Path
R=Path(__file__).resolve().parents[2];sys.path.insert(0,str(R/'scripts'))
from t05_pe import PE
from capstone import Cs,CS_ARCH_X86,CS_MODE_64
from t21b_control_flow import ReaderCFG
from t14_rtti_census import parse_rtti
pe=PE(Path('D:/tmp2b/fm24/input/editor.exe'));pe.pe.parse_data_directories(directories=[3]);md=Cs(CS_ARCH_X86,CS_MODE_64);md.detail=True

def ins(o): return next(md.disasm(pe.raw[o:o+15],pe.f2va(o),count=1))
def fmt(i): return f'{pe.va2f(i.address):08x} {i.address:x} {i.bytes.hex():23} {i.mnemonic:8} {i.op_str}' + (f' ; -> {pe.va2f(i.operands[0].imm):x}' if i.mnemonic.startswith(('j','call')) and i.operands[0].type==2 and pe.va2f(i.operands[0].imm)!=None else '')
def cfg(o):
 c=ReaderCFG(pe,md,o);print(f'Start {o:x} End {c.function_end_off:x} len {len(c.instructions)} external {c.external_edges}');print('\n'.join(map(fmt,[c.instructions[k] for k in sorted(c.instructions)])))
def span(o,n):print('\n'.join(map(fmt,md.disasm(pe.raw[o:o+n],pe.f2va(o)))))
if len(sys.argv)>1:
 for a in sys.argv[1:]:
  o,*n=a.split(':');o=int(o,16)
  if n:span(o,int(n[0],16))
  else:cfg(o)
else:
 m=json.loads((R/'evidence/fm24/reports/editor_schema/master.json').read_bytes());p=[x for x in m['entities']['club.xml'][0]['fields'] if x['field']=='CSrs'];print(json.dumps(p,indent=2))
 print('t24:',*[x for f in sorted((R/'scratch/t24/out').glob('subtables.part00*.json')) for x in json.loads(f.read_bytes())['nested_fields'] if x['parent']=='CSrs'],sep='\n')
 vt=0x141884988;v=pe.va2f(vt);print(parse_rtti(pe,vt));
 for k in [2,19,20,21]:
  va=struct.unpack_from('<Q',pe.raw,v+8*k)[0];o=pe.va2f(va);i=ins(o);print(k,fmt(i));
  if i.mnemonic=='jmp':o=pe.va2f(i.operands[0].imm)
  cfg(o)
 span(0xf49a2b,0x90)
 os.environ['FM24_DB_DIR']=str(R/'scratch/data');import fm24_dump as db
 c=db._reader()
 for a in ['client','server']:
  d=c['list_tables'](db.DB_DIR/(a+'_db.dat'),a+'_db.dat'); print(a,len(d),*[x for x in d if x['table_id']==62]);print([(x['table_id'],x['record_count_header']) for x in d if x['table_id'] in (3,21,25,26)])
 raw=db.load_payload(c,'server',62);print('payload',len(raw),raw[:13].hex(),raw[-9:].hex()); print('selectors',set(raw[13:-9:42]));
 for code in ['CSrs']:
  magic=code.encode()[::-1]; print(code,[hex(i) for i in range(0xe70000,0xec0000) if pe.raw.startswith(magic,i)])

